CREATE OR REPLACE FUNCTION public.product_intake_approve_reviewed_product(p_submission_id uuid, p_final_payload jsonb, p_spec_operations jsonb, p_reviewed_by text, p_reviewed_at timestamp with time zone DEFAULT now(), p_review_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_scanned_type text;
  v_scanned_value text;
  v_normalized_value text;
  v_final_payload jsonb := p_final_payload;
  v_approval_result jsonb;
  v_approved_product_id uuid;
BEGIN
  SELECT submission.scanned_identifier_type, submission.scanned_identifier_value
  INTO v_scanned_type, v_scanned_value
  FROM public.product_submissions AS submission
  WHERE submission.id = p_submission_id;

  IF v_scanned_type IS NOT NULL AND v_scanned_value IS NOT NULL THEN
    v_normalized_value := public.product_intake_review_normalize_identifier_value(
      v_scanned_type,
      v_scanned_value
    );

    IF v_normalized_value <> '' AND NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(
        COALESCE(p_final_payload -> 'identifiers', '[]'::jsonb)
      ) AS incoming(identifier)
      WHERE incoming.identifier ->> 'type' IN ('ean', 'gtin', 'barcode')
        AND public.product_intake_review_normalize_identifier_value(
              incoming.identifier ->> 'type',
              incoming.identifier ->> 'value'
            ) = v_normalized_value
    ) THEN
      v_final_payload := jsonb_set(
        v_final_payload,
        '{identifiers}',
        COALESCE(v_final_payload -> 'identifiers', '[]'::jsonb)
          || jsonb_build_array(
               jsonb_build_object(
                 'type', v_scanned_type,
                 'value', v_scanned_value,
                 'source', 'scan'
               )
             ),
        true
      );
    END IF;
  END IF;

  v_final_payload := public.product_identifier_prepare_final_payload_identifiers(
    v_final_payload,
    NULL
  );

  v_approval_result := public.product_intake_approve_reviewed_product_before_scanned_identifier(
    p_submission_id,
    v_final_payload,
    p_spec_operations,
    p_reviewed_by,
    p_reviewed_at,
    p_review_notes
  );

  v_approved_product_id := (v_approval_result ->> 'product_id')::uuid;

  UPDATE public.products
  SET
    net_content_value = NULLIF(v_final_payload #>> '{product,net_content_value}', '')::numeric,
    net_content_unit = NULLIF(v_final_payload #>> '{product,net_content_unit}', ''),
    updated_at = pg_catalog.now()
  WHERE id = v_approved_product_id;

  RETURN v_approval_result;
END;
$function$
